new file mode 100644
index 0000000..3e4ea90
--- /dev/null
+++ b/server/src/guards/forgot-password-throttle.guard.ts
@@ -0,0 +1,56 @@
+import {
+  CanActivate,
+  ExecutionContext,
+  HttpException,
+  HttpStatus,
+  Injectable,
+} from '@nestjs/common';
+
+const WINDOW_IN_MS = 60 * 1000;
+const MAX_ATTEMPTS = 5;
+const MAX_CLIENTS = 10000;
+
+type ClientAttempts = {
+  count: number;
+  resetAt: number;
+};
+
+@Injectable()
+export class ForgotPasswordThrottleGuard implements CanActivate {
+  private readonly attempts = new Map<string, ClientAttempts>();
+  private lastCleanupAt = 0;
+
+  canActivate(context: ExecutionContext): boolean {
+    const request = context.switchToHttp().getRequest();
+    const client =
+      request.ip || request.socket?.remoteAddress || request.connection?.remoteAddress || 'unknown';
+    const now = Date.now();
+    let attempts = this.attempts.get(client);
+
+    if (attempts && attempts.resetAt <= now) {
+      this.attempts.delete(client);
+      attempts = undefined;
+    }
+
+    if (!attempts) {
+      this.cleanup(now);
+
+      if (this.attempts.size >= MAX_CLIENTS) {
+        throw new HttpException('Too many requests', HttpStatus.TOO_MANY_REQUESTS);
+      }
+
+      this.attempts.set(client, {
+        count: 1,
+        resetAt: now + WINDOW_IN_MS,
+      });
+      return true;
+    }
+
+    if (attempts.count >= MAX_ATTEMPTS) {
+      throw new HttpException('Too many requests', HttpStatus.TOO_MANY_REQUESTS);
+    }
+
+    attempts.count += 1;
+    return true;
+  }
+
+  private cleanup(now: number): void {
+    if (now - this.lastCleanupAt < WINDOW_IN_MS) return;
+
+    for (const [client, attempts] of this.attempts) {
+      if (attempts.resetAt <= now) this.attempts.delete(client);
+    }
+    this.lastCleanupAt = now;
+  }
+}

